// The menu bar item (docs/phase-1.md 10.6, openspec add-desktop-devices-knowledge): the model of
// the Tray title, tooltip and menu from the counts. index.ts applies it to an Electron `Tray`.
import { AwUnreachableError } from "@aw/client";
import type { SyncStatusReply, Task } from "../shared/channels.ts";

// The menu bar icon (generated by scripts/icons.ts from the AW mark).
export { TRAY_ICON_PNG_BASE64 } from "./tray-icon.ts";

export type TrayAction = "sync-now" | "open" | "quit";

export type TrayItem =
  | { type: "text"; label: string }
  | { type: "action"; label: string; action: TrayAction; accelerator?: string }
  | { type: "separator" };

export interface TrayModel {
  title: string;
  tooltip: string;
  items: TrayItem[];
}

export interface TrayCounts {
  /** The tasks in the "Needs you" lane, or null before the first load. */
  needsYou: number | null;
  /** The items that the peers still need, or null when the sync state is not known. */
  unsynced: number | null;
  /** False when awd is not reachable. */
  online: boolean;
}

/** The tasks in the "Needs you" lane of all workspaces. */
export function countNeedsYou(workspaces: { tasks: Task[] }[]): number {
  return workspaces.reduce(
    (n, w) => n + w.tasks.filter((t) => !t.archived && t.needs_you_lane).length,
    0,
  );
}

/** The changes that the peers still need (the sum of `needItems`). */
export function countUnsynced(status: SyncStatusReply): number {
  return status.peers.reduce((n, p) => n + Math.max(0, p.needItems), 0);
}

function plural(n: number, one: string, many: string): string {
  return `${n} ${n === 1 ? one : many}`;
}

export function trayModel(counts: TrayCounts): TrayModel {
  const items: TrayItem[] = [];
  if (!counts.online) {
    items.push({ type: "text", label: "awd is not reachable" });
  } else {
    if (counts.needsYou !== null) {
      items.push({
        type: "text",
        label: counts.needsYou === 0 ? "Nothing needs you" : `${counts.needsYou} need you`,
      });
    }
    if (counts.unsynced !== null) {
      items.push({
        type: "text",
        label:
          counts.unsynced === 0
            ? "All changes synced"
            : `${plural(counts.unsynced, "change", "changes")} not synced`,
      });
    }
  }
  items.push(
    { type: "separator" },
    { type: "action", label: "Sync now", action: "sync-now" },
    { type: "action", label: "Open Agent Workspace", action: "open" },
    { type: "separator" },
    { type: "action", label: "Quit Agent Workspace", action: "quit", accelerator: "CmdOrCtrl+Q" },
  );
  const title = counts.online && counts.needsYou ? String(counts.needsYou) : "";
  const tooltip = !counts.online
    ? "Agent Workspace · awd is not reachable"
    : `Agent Workspace · ${counts.needsYou ?? 0} need you`;
  return { title, tooltip, items };
}

/**
 * The counts after a failed background load: only an unreachable awd hides the counts. Another
 * error (for example 503 `not_ready` of one workspace) keeps the last counts (devices-kb review 8).
 */
export function countsAfterError(counts: TrayCounts, error: unknown): TrayCounts {
  return error instanceof AwUnreachableError ? { ...counts, online: false } : counts;
}
